declare const ViewerEventSchema: z.ZodUnion<readonly [z.ZodObject<{
    destination: z.ZodString;
    sub_type: z.ZodString;
    type: z.ZodLiteral<"inbound">;
    value: z.ZodType<JsonValue, unknown, z.core.$ZodTypeInternals<JsonValue, unknown>>;
}, z.core.$strip>, z.ZodObject<{
    destination: z.ZodString;
    type: z.ZodLiteral<"cli_command">;
    value: z.ZodType<JsonValue, unknown, z.core.$ZodTypeInternals<JsonValue, unknown>>;
}, z.core.$strip>]>;
type ViewerEvent = z.infer<typeof ViewerEventSchema>;

/**
 * Async-iterable wrapper over the `cli_command` line stream produced
 * by `invokeCliRequest`. Used by the generated viewer execute
 * functions; plugin authors normally receive one rather than
 * constructing one.
 *
 * Each raw line is zod-parsed with `schema` — typically
 * `z.union([CliOutputErrorSchema, <ResponseSchema>])`, so error
 * envelopes and response values surface as plain union members
 * rather than thrown exceptions.
 *
 * Before parsing, externally-tagged aggregate layers are unwrapped:
 * the cli prints the aggregate `ResponseItem` wire shape (e.g.
 * `{"Config":{"Viewer":{"Get":{}}}}`), so single-key object wrappers
 * are peeled until the schema parses — the JS mirror of
 * `extract_leaf` in `objectiveai-cli/src/executor.rs`.
 *
 * The host's synthetic `{"type":"end"}` terminator line is consumed
 * (it ends iteration) and never yielded.
 */
declare class CliStream<T> implements AsyncIterable<T> {
    private readonly source;
    private readonly schema;
    constructor(source: AsyncIterable<unknown>, schema: z.ZodType<T>);
    [Symbol.asyncIterator](): AsyncIterator<T>;
    /** Collect every remaining item. */
    toArray(): Promise<T[]>;
    /**
     * Resolve the first item and discard the rest of the stream
     * (releasing the underlying message listener). `undefined` when the
     * stream ends without yielding — a unary command that printed
     * nothing before the end marker.
     */
    first(): Promise<T | undefined>;
}

/**
 * The viewer-iframe → host cli invocation transport. Lives in its own
 * module (rather than `./index`) so the generated execute functions
 * under `./command/` can import it without a circular dependency on
 * the viewer barrel.
 */
/**
 * Run a typed cli request on the host. `request` is the serde JSON of
 * the Rust SDK's `cli::command::Request` enum (the `path`-tagged
 * shape); the host deserializes it and lowers it to argv via
 * `into_command()` — Request→argv stays canonical in Rust, and raw
 * argv invocation deliberately does not exist on this side.
 *
 * Returns an `AsyncIterable<unknown>` over the JSONL output lines the
 * cli emits: `{"type":"error",…}` envelopes or response lines,
 * terminated by the host's synthetic `{"type":"end"}` marker.
 *
 * The plugin author never specifies `destination` — the host bridge
 * derives it from the iframe's identity. To run multiple cli
 * invocations sequentially, `await` each iterator to completion
 * before starting the next; concurrent invocations from the same
 * iframe produce interleaved streams that this shim cannot demux
 * (no per-invocation sub_type on `cli_command` events).
 *
 * Requires the objectiveai cli to be installed on the host
 * (`~/.objectiveai/objectiveai`). When the spawn fails the host
 * streams back a `{"type":"error",…}` envelope followed by
 * `{"type":"end"}`, so the iterator still terminates.
 *
 * This is the transport behind the generated viewer execute
 * functions; plugin authors normally call those instead.
 */
declare function invokeCliRequest(request: unknown): AsyncIterable<unknown>;

